from base_sensor import BaseVirtualSensor

class INA3221_Simulator(BaseVirtualSensor):
    def __init__(self):
        super().__init__()
        self.regs = {
            0x00: 0x7127,  # CONFIG
            0x01: 0x0000,  # SHUNT1
            0x02: 0x0000,  # VBUS1
            0x03: 0x0000,  # SHUNT2
            0x04: 0x0000,  # VBUS2
            0x05: 0x0000,  # SHUNT3
            0x06: 0x0000,  # VBUS3
            0x07: 0x7FF8,  # CRIT1
            0x08: 0x7FF8,  # WARN1
            0x09: 0x7FF8,  # CRIT2
            0x0A: 0x7FF8,  # WARN2
            0x0B: 0x7FF8,  # CRIT3
            0x0C: 0x7FF8,  # WARN3
            0x0D: 0x0000,  # SHUNT_SUM
            0x0E: 0x7FFE,  # SHUNT_SUM_LIMIT
            0x0F: 0x0002,  # MASK_ENABLE
            0x10: 0x2710,  # PV_UPPER
            0x11: 0x2328,  # PV_LOWER
            0xFE: 0x5449,  # MANUF_ID
            0xFF: 0x3220   # DIE_ID
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:#04x}")

        value = self.regs[addr]

        if nbytes == 1:
            return (value >> 8) & 0xFF
        else:
            return value

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:#04x}")

        if nbytes == 1:
            mask = 0xFF00
            data = (data << 8) & mask
            self.regs[addr] = (self.regs[addr] & ~mask) | data
        else:
            self.regs[addr] = data

        # Handle special cases for read-only registers
        if addr in [0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x0D, 0xFE, 0xFF]:
            self.regs[addr] = 0x0000  # Reset read-only registers to default value

        # Handle reset functionality for CONFIG register
        if addr == 0x00 and (data & 0x8000):
            self.reset_registers()

    def reset_registers(self) -> None:
        for addr, reset_value in self.regs.items():
            self.regs[addr] = reset_value
